        mapped.z = sqrt(max(0.0, 1.0 - dot(mapped.xy, mapped.xy)));
        normal = normalize(lerp(
            normal, input.tangent * mapped.x + input.binormal * mapped.y + normal * mapped.z,
            surface.w));
